return {
  [809242973963776] = "Tosse, tosse, tosse! Essa maldita gripe arruinou completamente minha garganta!",
  [809242973995008] = "Eu tenho que pensar, existe alguém mais assustador que Gehrman...",
  [809242974060544] = "Devo dizer, Palide, seu trabalho desta vez é perfeito. Mas isso ocorre claramente porque o modelo é muito notável.",
  [809242974020608] = "Pare de falar bobagem! Pegue isso! <P_Heart> (balança e erra novamente) </>",
  [809242974077696] = "Instrutor Oros, hum... por favor, não diga a ele que eu te contei.",
  [809242974077440] = "Quem é?",
  [809242974077184] = "Mas parece que ouvi um cavalheiro mencionando este livro recentemente. Talvez, quero dizer, talvez, você possa perguntar a ele.",
  [809242974076928] = "E-esse tipo de livro não parece muito honroso... eu não deveria ter revelado isso casualmente, mas...",
  [809242974076672] = "Você está realmente bem informado. Você sabe quem encomendou “A Arte da Disciplina”?",
  [809242974076416] = "Obrigado. Ouvi dizer que algo aconteceu com o servo e foi um problema para você recuperar esses livros para nós.",
  [809242974076160] = "Senhorita Christine, aqui estão os livros que você encomendou.",
  [809242974075904] = "Talvez você pudesse perguntar à Srta. Christine; ela está sempre bem informada.",
  [809242974075648] = "Eh? Alguém em nosso clube lê esse tipo de livro? Verdadeiramente envergonhado, eu realmente não sei.",
  [809242974075392] = "Ah, que pena. Obrigado pela sua gentileza, você é tão entusiasmado e prestativo.",
  [809242974075136] = "Ele foi atropelado por uma carruagem e foi ao médico para uma emergência.",
  [809242974074880] = "Você na verdade... ah! Como posso incomodar um membro do clube para fazer uma coisa dessas? Estou realmente envergonhado. Não fui eu que mandei aquele jovem, Tano? Onde ele está?",
  [809242974074624] = "Sebastian, aqui está um lote de livros que você encomendou. Eu ajudei a trazê-los de volta.",
  [809242974074368] = "Além disso, aqui está a nota de entrega para você. Isso foi trazido por aquele azarado chamado Tano agora há pouco, e a pessoa que os encomendou está escrito nele.",
  [809242974074112] = "Muito obrigado! Aqui, por favor, leve-os!",
  [809242974073856] = "Parece que é um pequeno favor...",
  [809242974073600] = "Isso é ótimo! Deve ser muito conveniente para você retornar ao clube, poderia devolver esses livros?",
  [809242974073344] = "Na verdade, sou membro desse clube.",
  [809242974073088] = "Você o conhece? Ele é supervisor de trabalho em um clube, sua personalidade é, uh... muito séria.",
  [809242974072832] = "Sebastião? ...O clube que você mencionou poderia ser...",
  [809242974072576] = "Tsk, esses livros não podem ser empilhados aqui... Aquele rígido Sr. Sebastian também escreverá uma carta para me condenar.",
  [809242974072320] = "Mas como você deve ter visto, o funcionário do clube responsável pela retirada da mercadoria acabou de ser atropelado por uma carruagem ali, seus ossos não parecem bons, ele precisa consultar um médico.",
  [809242974072064] = "Isso mesmo, azar. Um clube encomendou-me um lote de livros.",
  [809242974071808] = "Olá, aconteceu alguma coisa?",
  [809242974071040] = "Olá! Vapor acima, este encontro deve ser a orientação dos deuses...",
  [809242974070784] = "Olá! Olá! Minha câmera e eu estávamos ansiosos para conhecê-lo!",
  [809242974070528] = "Sr. Kodak, por favor, espere e não chore! Nosso homem do momento, obrigado, teremos a chance de nos encontrar novamente na próxima vez!",
  [809242974070272] = "Suspiro, Palide, você encontrou um modelo tão bom, mas eles são tão rígidos quanto o gelo e a neve nas fotos.",
  [809242974070016] = "Por favor, revele as fotos normalmente.",
  [809242974069760] = "Continua tão perfeito como sempre! Suspiro... ainda não consigo adicionar algumas... por exemplo, flores na neve...",
  [809242974069248] = "Não importa, o Sr. Kodak não irá contra seus pedidos, desde que você os especifique!",
  [809242974068992] = "Na verdade... ele se sentiu muito arrependido nas últimas vezes. Eu o consolei várias vezes antes que ele aceitasse.",
  [809242974068736] = "Ele não deveria querer adicionar padrões a esse tipo de foto, certo?",
  [809242974068224] = "Não se preocupe, já escolhi um excelente local de filmagem, com certeza vai impressionar seu comportamento. Vamos, estamos indo para a Montanha Nevada Hornacis!",
  [809242974067968] = "O que isso significa?",
  [809242974067712] = "Este plano de filmagem é mais grandioso do que antes, espero capturar sua atitude de encarar o mundo e desprezar tudo!",
  [809242974067200] = "Eu certamente irei! Nosso homem do momento, obrigado, teremos a chance de nos encontrar novamente na próxima vez!",
  [809242974066944] = "Tudo bem, tudo bem. Você ainda é tão sério e rigoroso. Se ao menos Palide pudesse aprender um por cento de suas virtudes.",
  [809242974066688] = "Por favor, revele as fotos normalmente e claramente.",
  [809242974066432] = "Continua tão perfeito como sempre! Vapor acima, posso pedir para lavar alguns padrões lindos para você desta vez?",
  [809242974065920] = "Suspiro, desde que seja o seu pedido, ele atenderá e executará. É uma pena que nunca possa fazer nada em relação a esse cavalheiro.",
  [809242974065664] = "Espero que ele revele as fotos normalmente.",
  [809242974065152] = "Sabor especial – refere-se a atuar como um personagem diferente de si mesmo, mas que possui as características da época. Então vamos para o Distrito das Fábricas!",
  [809242974064896] = "Sim! As fotos tiradas de você da última vez foram muito aclamadas! Desta vez planejei um novo local para capturar imagens com um sabor especial para vocês!",
  [809242974064384] = "Obrigado, teremos a chance de nos encontrar novamente na próxima vez!",
  [809242974064128] = "Tudo bem, tudo bem. Obrigado novamente pela sua cooperação.",
  [809242974063872] = "Por favor, revele as fotos normalmente.",
  [809242974063616] = "Continua tão perfeito como sempre! E tem o sabor especial conferido pela modelo! Vapor acima, eu—",
  [809242974063360] = "Ah, Palide, você está de volta. Deixe-me ver o filme desta vez...",
  [809242974063104] = "Claro, claro, contanto que você conte a ele seriamente! Suspiro, aquele senhor é sempre muito rígido comigo, e apenas tolerante quando atira em você.",
  [809242974062848] = "Espero que ele apenas revele as fotos corretamente.",
  [809242974062592] = "Como esperado de você, nosso homem do momento, o Sr. Kodak, também não conseguirá largar o filme desta vez!",
  [809242974062336] = "Ah, ah, é um impacto artístico, não afetará sua saúde e segurança. Vamos! Vamos para a praça!",
  [809242974062080] = "Sim! As fotos tiradas para você da última vez foram bem recebidas! Desta vez planejei um novo local para filmar imagens impactantes de vocês!",
  [809242974061824] = "Te encontrei de novo, a estrela do Clube!",
  [809242974061568] = "Ele certamente irá! Senhor, obrigado pela sua cooperação. Talvez você possa ver essas imagens preciosas em breve!",
  [809242974061312] = "Por favor, apenas revele as fotos normalmente...",
  [809242974061056] = "Você gostaria de alguns efeitos de luz cor de rosa? Você gostaria de adicionar um pouco de efeitos de envelhecimento vintage? Ou-",
  [809242974060800] = "Vapor acima, apostarei o aprendizado da minha vida na conclusão de um desenvolvimento perfeito!",
  [809242974060288] = "Oh, Palide, você voltou com nosso homem do momento. Deixe-me ver esses filmes...",
  [809242974060032] = "Desculpe, eu realmente preciso incomodá-lo para fazer uma viagem; O Sr. Kodak precisa manter sua licença de autorização.",
  [809242974059776] = "Venha, falta o último passo, volte ao clube e entregue o filme ao Sr. Kodak.",
  [809242974059520] = "Como esperado de você, nosso homem do momento; até o exigente Sr. Kodak ficaria sem palavras depois de ver isso!",
  [809242974059264] = "Não se preocupe! Todas as despesas são custeadas pelo clube, basta mostrar seu comportamento sob minha orientação!",
  [809242974059008] = "Desta vez, por favor, permita que o atualmente popular Restaurante Coastline me permita filmar imagens preciosas de você degustando bons vinhos.",
  [809242974058752] = "Planejamos muitos locais significativos e únicos, mas não se preocupe, farei as filmagens gradualmente!",
  [809242974058496] = "Espero registrar seu comportamento em determinadas ocasiões, aguardo sua cooperação!",
  [809242974058240] = "Nosso trabalho é capturar imagens maravilhosas para todos os membros, especialmente para um homem importante como você.",
  [809242974057984] = "Ah, sim, vim trabalhar no seu clube com o Sr. Kodak há pouco tempo, é normal que você não me conheça.",
  [809242974057728] = "Finalmente conheci você, a estrela do Clube!",
  [809242974057472] = "Mas devo lembrá-lo de uma coisa: as coisas que você capturar a seguir podem não ser todas agradáveis. Afinal, é o Festival Estranho... Heh, desde que seja interessante.",
  [809242974057216] = "Apenas me siga. Vou levá-lo a um lugar todos os dias. Quanto a onde fica, você naturalmente saberá quando chegarmos.",
  [809242974056960] = "Para o Sr. Tolo... decidi aceitar esta comissão. Então, onde devo ir para tirar fotos?",
  [809242974056704] = "Você saberá mais cedo ou mais tarde. Antes disso, por que não decidir se deseja aceitar esta comissão fotográfica? Claro, isto é apenas uma sugestão; depende de você aceitar ou não. Só que seria muito chato se você perdesse.",
  [809242974056448] = "Quem exatamente é você?",
  [809242974056192] = "Shh, fale baixo.",
  [809242974055936] = "Essa existência... poderia ser—",
  [809242974055680] = "E esses negativos que preservam a humanidade se tornarão a ajuda para que essa existência mantenha a humanidade durante o sono profundo.",
  [809242974055424] = "Cada canto que você vê agora pode esconder vestígios deixados pela história. Eles estão se dissipando lentamente, mas se você tirar uma foto com negativo espiritualidade, poderá preservar esses traços.",
  [809242974055168] = "Uma apresentação muito especial está sendo realizada aqui – chamada de “Festival Estranho”. O véu entre o Mundo Espiritual e a realidade torna-se tênue neste momento, tão tênue que essas histórias dissipadas ressurgirão.",
  [809242974054912] = "Para ser mais preciso, eu estava esperando por uma pessoa viva que soubesse tirar fotos.",
  [809242974054656] = "Você estava esperando por mim?",
  [809242974054400] = "Você finalmente veio.",
  [809242974054144] = "Hehe, é isso mesmo? Estou ansioso pelo próximo lote de conteúdo também. Até mais.",
  [809242974053888] = "Sinto que estou começando a gostar de fotografia.",
  [809242974053632] = "Mas você não capturou um momento dela sob a luz do sol com sua câmera?",
  [809242974053376] = "Isto é apenas um vestígio da história; ele se dissipará mais cedo ou mais tarde.",
  [809242974053120] = "Ela desapareceu...",
  [809242974052864] = "Tudo bem, as filmagens de hoje terminam aqui, ansioso pelo nosso próximo encontro.",
  [809242974052608] = "O choque causado pela imagem é muito mais profundo do que os slogans. Estou realmente ansioso pela reação das pessoas depois de revelar as sombras.",
  [809242974052352] = "Talvez, se você tiver oportunidade, você possa enviar artigos para um jornal como alguém fez uma vez.",
  [809242974052096] = "A fornalha da fábrica está sempre queimando sem parar; a vida nada mais é do que um grão de cinza diante da época.",
  [809242974051840] = "Vamos encerrar por aqui por hoje, estou ansioso para nosso próximo encontro.",
  [809242974051584] = "Hehe, é só que você tem que tomar cuidado para não tropeçar em alguma coisa na neve mais tarde... hehe...",
  [809242974051328] = "Seus corpos espirituais tiraram uma foto com a tranquilidade atual; para eles, pode ser considerado uma realização.",
  [809242974051072] = "Suspiro... a guerra ceifou muitas vidas e destruiu o futuro de muitas pessoas.",
  [809242974050816] = "Vamos parar as filmagens de hoje aqui, vamos nos encontrar novamente na próxima vez.",
  [809242974050560] = "Pessoas de diferentes fases podem se encontrar na mesma foto; é realmente interessante.",
  [809242974050304] = "As filmagens de hoje terminam aqui. Estou realmente ansioso para ver as cenas interessantes que capturaremos na próxima vez.",
  [809242974050048] = "Essa pessoa é realmente interessante, não é?",
  [809242974049792] = "Será que a memória às vezes é boa e às vezes ruim, ou há algum outro motivo?",
  [809242974049536] = "A humanidade é verdadeiramente maravilhosa. Por hoje é isso, estou ansioso pelo nosso próximo encontro.",
  [809242974049280] = "Mmm, ele morreu naquela Grande Névoa e nunca mais retornará, mas como você viu, talvez ele também nunca tenha partido.",
  [809242974049024] = "Ele... o pai da criança já morreu?",
  [809242974048768] = "Claro, mas não apenas nós. Tudo bem, a fotografia de hoje termina aqui.",
  [809242974048512] = "Nós?",
  [809242974048256] = "Hehe, alguém está observando eles? Essa frase não está errada.",
  [809242974048000] = "Vi um conteúdo muito interessante hoje, vamos parar por aqui.",
  [809242974047744] = "Destino, morte, promessas, essas coisas são verdadeiramente maravilhosas.",
  [809242974047488] = "Não esqueceu. Foi até o local onde estavam os restos mortais de Welch e o tem acompanhado.",
  [809242974047232] = "Será que ele vai esquecer tudo isso depois de acordar? Hehe.",
  [809242974046976] = "Parece que esse gato também é uma criatura Beyonder, prestes a cair em um sono profundo.",
  [809242974046720] = "Hehe, a fotografia de hoje acabou, vamos nos encontrar novamente na próxima vez.",
  [809242974046464] = "Olha, que interessante. Na verdade, uma árvore é mais confiável que a memória humana.",
  [809242974046208] = "Isso me deixa ansioso pelo conteúdo da próxima filmagem. Hehe, vamos nos encontrar novamente na próxima vez.",
  [809242974045952] = "Comida de cachorro? Mas não são essas pessoas? Esta metáfora é verdadeiramente interessante.",
  [809242974045696] = "Sinto como se tivesse sido pego de surpresa e alimentado com a boca cheia de comida de cachorro...",
  [809242974045440] = "Era uma vez uma senhora neste castelo que olhava para fora do castelo o dia todo.",
  [809242974045184] = "Tire uma foto aqui e você pode me dizer o que pensa.",
  [809242974044928] = "As pessoas podem ver a prosperidade na superfície da cidade, mas por trás disso, que tipo de coisas interessantes existem?",
  [809242974044672] = "A Fábrica é sempre chamada de espinha dorsal da época.",
  [809242974044416] = "O vento e a neve aqui sopraram com mais força desde aquela guerra. A neve espessa cobriu muitos vestígios.",
  [809242974044160] = "Há pessoas por perto, o que elas estão dizendo?",
  [809242974043904] = "Parece que o cenário desta pequena cidade é como uma pintura a óleo. Ficando aqui por um tempo, o tempo parece se esticar infinitamente.",
  [809242974043648] = "Venha, vamos ver que coisas interessantes iremos capturar hoje.",
  [809242974043392] = "A atmosfera deste restaurante é muito boa.",
  [809242974043136] = "Quero tentar tirar uma foto; talvez eu possa cumprir brevemente o desejo deles...",
  [809242974042880] = "Nada mal, você observa com muito cuidado. Eles estão esperando por alguém, mas talvez nunca esperem por ele.",
  [809242974042624] = "Aquela mãe e filho estão esperando por alguém?",
  [809242974042368] = "Olha aí, que cena animada; você pode tirar uma foto disso. Não se preocupe, roubei temporariamente sua existência, eles não conseguem perceber você.",
  [809242974042112] = "Este lugar sempre reúne lágrimas, raiva, lamentações, desespero e os segredos do coveiro.",
  [809242974041856] = "O Cemitério é realmente um bom lugar para o Festival Estranho.",
  [809242974041600] = "Olha, tem uma memória da história ali. Pegue sua câmera e deixe o filme relembrar esse momento para eles.",
  [809242974041344] = "Às vezes, a morte não é o fim. Ainda existem muitos vestígios de memórias neste mundo.",
  [809242974041088] = "Essa memória está prestes a se dissipar em breve – mas se você tirar uma foto dela, ela poderá permanecer.",
  [809242974040832] = "Há pai e filho debaixo daquela árvore; uma vez eles plantaram uma árvore aqui.",
  [809242974040576] = "O cenário aqui é muito bom. Olha, poder ver vestígios de corpos espirituais em um lugar como este é interessante.",
  [809242974040320] = "Obrigado pelo seu trabalho árduo, gentil Sr./Sra. {{|}}!",
  [809242974040064] = "Por favor, espere um momento! Você é o Sr./Sra. {{|}} da Blackthorn Security Company, certo? Você pode me fazer um pequeno favor?",
  [809242974039808] = "Galhos e folhas formam uma escada suave, me levando a dormir para sempre debaixo d'água...",
  [809242974039552] = "Este lugar tem os melhores ovos fritos...",
  [809242974039296] = "Quando Kila voltará...",
  [809242974039040] = "Esta é uma receita trazida por um viajante há setenta anos, o licor forte mais famoso do Golden Autumn Lake!",
  [809242974038784] = "Muito obrigado! Essas páginas devem estar perto do Lago Golden Autumn, conto com você!",
  [809242974038528] = "Deixe-me ajudá-lo a encontrá-los.",
  [809242974038272] = "Então gravei tudo, mas agora... estão todos espalhados...",
  [809242974038016] = "Sofro de amnésia intermitente; Esqueço tudo de ontem quando acordo todos os dias.",
  [809242974037760] = "Suas memórias?",
  [809242974037504] = "Devo encontrá-los; são minhas únicas lembranças.",
  [809242974037248] = "Oh sim! Meu caderno foi espalhado pelo vento e as páginas estão flutuando por toda parte.",
  [809242974036992] = "Velho, você está procurando alguma coisa?",
  [809242974036736] = "Eu vou dar uma olhada.",
  [809242974036480] = "Se ao menos alguém pudesse lidar com ele.",
  [809242974036224] = "Logo na rua à frente, ele procura especificamente locais estreitos para se deitar. Você quer ir? Tenha cuidado, não se deixe enredar por ele.",
  [809242974035968] = "Onde está a pessoa de quem você está falando?",
  [809242974035712] = "Ele é simplesmente um canalha!",
  [809242974035456] = "Ele me roubou dinheiro novamente hoje... Eu estava dirigindo a carruagem e ele se jogou sob as rodas.",
  [809242974035200] = "Se esse for realmente o motivo, Sr./Sra. {{|}}, posso pedir que você ajude a cuidar desse velho senhor?",
  [809242974034944] = "Ah, é por causa disso? De vez em quando borrifo um pouco de perfume.",
  [809242974034688] = "Por favor, permita-me interromper, Srta. Enfermeira. Este velho senhor parece ter pulmões fracos; ele se sente desconfortável quando sente o cheiro do perfume em você.",
  [809242974034432] = "<P_Heart> (Parece que este velho está muito enojado com sua enfermeira, pode haver algum outro motivo.) </>",
  [809242974034176] = "Mas, senhor, você deve tomar seu remédio. Caso contrário, sua doença nunca irá melhorar...",
  [809242974033920] = "Não chegue perto de mim, mulher!",
  [809242974033408] = "Deusa do alto, abençoe esta pobre pessoa!",
  [809242974032640] = "<P_Heart> (Parece que tem alguém no telhado querendo pular de um lugar alto, esta é uma boa oportunidade para atuar como psicólogo.) </>",
  [809242974032384] = "Deusa Proteção, abençoe esta pobre pessoa!",
  [809242974032128] = "<P_Heart> (Parece que tem alguém no telhado querendo pular de um lugar alto.) </>",
  [809242974031872] = "Estou cansado de assistir. <P_Heart> (Gritando) </> Ei! Se você está planejando pular, então pule! Estamos todos esperando!",
  [809242974031616] = "Rugido, rugido, rugido! Rugido rugido!",
  [809242974031360] = "É uma honra poder animá-los e continuar divulgando os ensinamentos do Sr.",
  [809242974031104] = "Cantar... esse é realmente um bom método. Obrigado. A partir de amanhã aprenderei a cantar também!",
  [809242974030848] = "Não desanime. Talvez as palavras do livro possam ser cantadas em canções simples para as crianças lembrarem.",
  [809242974030592] = "Eu realmente não sei como fazer as crianças ouvirem a 'Sagrada Escritura do Louco'. Eu realmente não sou um pastor qualificado!",
  [809242974030336] = "Durante a oração de hoje, algumas crianças pularam, gritando “chato” e “não entendo”.",
  [809242974030080] = "O Sr. “Tolo” é um Deus gentil e não irá culpar você. Aconteceu alguma coisa na Igreja?",
  [809242974029824] = "Que o 'Tolo' perdoe meus pecados. Como pastor de igreja, falhei em difundir adequadamente Sua fé...",
  [809242974029568] = "Também deveríamos aproveitar o dia enquanto somos jovens e tentar!",
  [809242974029312] = "Pensando nisso agora, Roselle era apenas um nobre menor e discreto no início, e ele só se tornou imperador por meio de seus próprios esforços.",
  [809242974029056] = "Bem cantado! Roselle foi o único imperador que realmente se importava com o povo!",
  [809242974028800] = "Senhor, houve um imperador na história como aquele que você descreveu. Por favor, permita-me cantar seus feitos.",
  [809242974028544] = "<P_Heart> (Eles parecem ter esquecido o Imperador Roselle... Esta é uma boa oportunidade para atuar como um Bardo.) </>",
  [809242974028288] = "Independentemente disso, eles vivem em palácios, enquanto nós três estamos espremidos em uma casa destruída. Qual imperador se preocupa com a vida das pessoas comuns?",
  [809242974028032] = "Suspiro, de que adianta discutir sobre isso? As libras provenientes da construção de fábricas e da venda de grãos não vão todas para o bolso do rei?",
  [809242974027776] = "O Rei de Feysac é o único rei bom! Metade do pão preto de toda Tingen vem de lá.",
  [809242974027520] = "Eu realmente gostaria de ter uma nota de dez libras para poder mostrar a vocês aquele 'Fundador da Nação' - Guilherme I!",
  [809242974027264] = "Meu filho está estudando no campo e a professora pediu que ele escrevesse uma redação intitulada 'Quem é o maior rei do seu coração?'",
  [809242974027008] = "Ah sim, tudo isso vai passar. Por que eu estava chorando tanto?",
  [809242974026752] = "<P_Heart> (Realizando sugestão emocional) </> Está tudo bem, tudo isso vai passar.",
  [809242974026496] = "<P_Heart> (Ele parece ter ficado com raiva, mas ainda não tem intenção de sair do telhado.) </>",
  [809242974026240] = "Não, não, não, não deveria ser assim! Isso não é justo!",
  [809242974025984] = "<P_Heart> (Realizar sugestão emocional) </> Todos os animais são iguais, mas alguns animais são mais iguais que outros.",
  [809242974025728] = "<P_Heart> (Ele parece ter ficado triste, mas ainda não tem intenção de sair do telhado.) </>",
  [809242974025472] = "Suspiro, o mundo é assim mesmo, o mundo é assim mesmo...",
  [809242974025216] = "<P_Heart> (Realizando sugestão emocional) </> Você é pó e ao pó retornará.",
  [809242974024960] = "<P_Heart> (Ele parece querer pular. Vamos tentar mudar suas emoções e pensamentos.) </>",
  [809242974024704] = "Hum? Quem é você e o que você quer? Se você também está planejando pular aqui, por favor, me dê alguns minutos.",
  [809242974024448] = "Todo mundo está me abandonando, só eu ainda persisto... *hic*, já estou me sentindo exausta.",
  [809242974024192] = "<P_Heart> (Resmungando) </> Hmm... *soluço*, já se passaram três anos... não, seis. Quantos anos faltam para poder ter uma casa em Tingen?",
  [809242974023936] = "<P_Heart> (Feliz) </> Rugido, rugido!",
  [809242974023680] = "Bom! Então vá! Recupere tudo que você perdeu!",
  [809242974023424] = "Rugido rugido! Rugido rugido! Rugido rugido!",
  [809242974023168] = "Você aprendeu tudo que acabei de te ensinar?",
  [809242974022912] = "Rugido?",
  [809242974022656] = "Venha, assim, deixe-me te ensinar a lutar!",
  [809242974022400] = "<P_Heart> (Sentindo-se deprimido) </> Rugido...",
  [809242974022144] = "Você foi intimidado?",
  [809242974021888] = "<P_Heart> (Ofendido) </> Rugido... rugido rugido...",
  [809242974021632] = "Pequeno babuíno, o que há de errado com você?",
  [809242974021376] = "Sou claramente apenas uma pessoa! Você está insultando meu personagem! Pegue isso!",
  [809242974021120] = "Você é o monstro! Como você se transformou em duas pessoas? São dois contra um agora! Isso é injusto!",
  [809242974020864] = "Uau! Como você cresceu quatro mãos? Seu monstro!",
  [809242974020352] = "<P_Heart> (Dizzy) </> Eu estive aqui o tempo todo... seus olhos estão pregando peças em você...",
  [809242974020096] = "<P_Heart> (Bêbado) </> Você claramente estava aí agora mesmo! Como você veio correndo até aqui em um piscar de olhos?",
  [809242974019840] = "<P_Heart> (balançando) </> Aquele seu soco... passou voando pela lateral...",
  [809242974019584] = "Pegue meu soco! - Huh? Para onde foi meu punho?",
  [809242974016768] = "<P_Heart> (Deixe-o terminar um dos relacionamentos para beneficiar três pessoas.) </>",
  [809242974014976] = "Você é... não, você é um adivinho?",
  [809242974014464] = "<P_Heart> (Voz ligeiramente trêmula) </> Frio... sinto um pouco de frio...",
  [809242974014208] = "<P_Heart> (Parece que eles podem passar um dia quente.) </>",
  [809242974013952] = "Mamãe, aqui estão suas roupas de volta!",
  [809242974013696] = "Louvado seja a Deusa! Este deve ser o favor da Deusa!",
  [809242974013440] = "Querida, sinto que ficou muito mais quente!",
  [809242974013184] = "<P_Heart> (Vamos usar Beyonder poderes para ajudá-los.) </>",
  [809242974012928] = "Está tudo bem, venha aqui, vista a roupa da mamãe...",
  [809242974012672] = "<P_Heart> (Voz trêmula) </> Papai, mamãe, estou com tanto frio...",
  [809242974012416] = "<P_Heart> (Tosse) </> Aham! Tanta fumaça preta... O que devo fazer?",
  [809242974012160] = "Por que a lenha não acende hoje...",
  [809242974011904] = "As lâmpadas da rua próximas quebraram repentinamente recentemente e eu não consegui ver nada quando saí do trabalho!",
  [809242974011648] = "Ela definitivamente irá.",
  [809242974011392] = "Espero que minha aprendiz possa retornar em breve.",
  [809242974011136] = "A lâmpada da rua está consertada! Agora posso andar à noite sem me preocupar.",
  [809242974010880] = "<P_Heart> (Parece perigoso. Vou dar uma olhada à noite...) </>",
  [809242974010624] = "Eles nem nos tratam como seres humanos! Perguntar? Perguntar é apenas uma perda de esforço!",
  [809242974010368] = "<P_Heart> (Segurando a testa) </> Essa lâmpada, vou perguntar de novo...",
  [809242974010112] = "O marido dela chamou a polícia, mas ainda não encontraram vestígios dela. <P_Heart> (Cospe) </> Um monte de gente inútil também!",
  [809242974009856] = "<P_Heart> (Raiva) </> Tenho uma aprendiz que percorreu esse caminho depois do trabalho há alguns dias e depois desapareceu, desapareceu!",
  [809242974009600] = "<P_Heart> (Desamparado) </> Eu relatei isso aos superiores, mas ninguém lidou com isso. Suspiro, eles não se importariam se vivêssemos ou morrêssemos.",
  [809242974008576] = "<P_Heart> (Eles parecem estar preocupados por causa de uma certa pessoa falecida.) </>",
  [809242974008320] = "Você tem razão. Devíamos dar ao Velho John uma morte decente.",
  [809242974008064] = "Você está louco? Onde o queimaríamos? Existe alguém entre nós disposto a tocá-lo? Aqui? Queimá-lo até virar cinzas na frente das crianças?",
  [809242974007808] = "Talvez... devêssemos simplesmente queimar o Velho John.",
  [809242974007552] = "Há um lugar que é assombrado. Devemos dar uma olhada?",
  [809242974007296] = "Isso é realmente maravilhoso! Não sei como te agradecer! Por favor, pegue isso; é a herança do Velho John. Ele não teve filhos, então tudo pertence a você agora.",
  [809242974007040] = "Fique tranquilo, ele não terá mais problemas. O Velho John agora é apenas um cadáver.",
  [809242974006784] = "<P_Heart> (Tremendo) </> Tem certeza, Sr./Sra. Bruxa {{|}}? Ele estava brilhando há pouco.",
  [809242974006528] = "O exorcismo acabou. Você pode enterrá-lo ou prefere a cremação?",
  [809242974006272] = "De qualquer forma, por favor, dê uma olhada nele e veja como você pode fazê-lo parecer... um pouco mais normal.",
  [809242974006016] = "Velho John, bem ali, aquele cadáver. Para ser sincero, também não sabemos o que aconteceu e não sabemos quem pode ajudar...",
  [809242974005760] = "Você pode me dizer o que aconteceu?",
  [809242974005504] = "Aham, por favor, deixe-me pedir desculpas pela minha imprudência. Independentemente de você ter vindo por causa da comissão que postei, espero que possa nos ajudar a verificar o Velho John.",
  [809242974005248] = "Minha Deusa, de onde você saiu? Oh, será que você usou bruxaria? Você é uma bruxa?",
  [809242974004992] = "<P_Heart> (Este grupo de gatinhos parece estar brigando, suas posturas de luta parecem esconder algum segredo.) </>",
  [809242974004736] = "Cinco minutos, senhora. Dê-nos apenas cinco minutos...",
  [809242974004480] = "<P_Heart> (Parece que o elogio foi eficaz. Vou deixar o caso para este oficial continuar cuidando.) </>",
  [809242974004224] = "Ok, antes do incidente acontecer, eu tinha acabado de sair do escritório de recrutamento da fábrica com Big John...",
  [809242974003968] = "Mas, por enquanto, você pode me contar o que aconteceu com Big John?",
  [809242974003712] = "<P_Heart> (Sussurrando) </> O que, realmente funcionou? Ah, claro, senhora. Mesmo depois do hoje mais aterrorizante, sempre haverá um amanhã.",
  [809242974003456] = "Não sei por que, mas de repente me sinto... muito mais calmo.",
  [809242974003200] = "<P_Heart> (Esta deve ser uma boa oportunidade para atuar como um Bardo, vamos tentar pacificar as emoções desta senhora.) </>",
  [809242974002944] = "Por favor, não se importe, mas acho que um especialista também deveria ser proficiente em alguns métodos de pacificar testemunhas.",
  [809242974002688] = "Como você pode ver, um assassinato acabou de acontecer aqui. Queremos perguntar à testemunha ocular sobre a situação, mas ela continua chorando aqui.",
  [809242974002432] = "Você é... Sr./Sra. {{PlayerName}}{{|}}, estou certo? Vi seu arquivo nos arquivos da delegacia; rotula você como um especialista na investigação de casos especiais.",
  [809242974002176] = "Tudo bem, tudo bem, senhora, você tem um lenço? Limpe-se primeiro... Ei, acho que já vi você antes!",
  [809242974001920] = "Eu não posso... Meu Big John, ele só... acabou de conseguir um emprego... Ah, não!",
  [809242974001664] = "Acalme-se, senhora. Eu sei que testemunhar tudo isso deixou você em pânico, mas você poderia reservar pelo menos cinco minutos para me contar o que aconteceu?",
  [809242974001408] = "<P_Heart> (Parece que eles não têm tempo para prestar atenção em mim, espero poder ajudar.) </>",
  [809242974001152] = "Copos? Por que preciso de um segundo par de óculos? Alguém sabe se tem uma ótica por aqui?",
  [809242974000896] = "Ah, não, tenho que me apressar e comprar uma passagem de trem. Ah, e minha bagagem! Meu Deus, nem sei como está o tempo lá!",
  [809242974000640] = "Deusa, estou quase decidindo concordar com ele!",
  [809242974000384] = "Coco deveria aceitar o convite, mas Ellie não deveria concordar com aquele cavalheiro, e Debbie deveria preparar um novo par de óculos.",
  [809242974000128] = "Como está, Sr./Sra. {{|}}? Você viu quais são nossas fortunas recentes?",
  [809242973999872] = "Muito obrigado, Sr./Sra. {{|}}. Estes são os nossos aniversários. Estamos todos muito ansiosos para conhecer nossa sorte recente.",
  [809242973999616] = "Oh! Debbie, Coco, parece que não precisamos folhear os livros para interpretá-los!",
  [809242973999360] = "Olá meninas, parece que vocês estão fazendo astrologia adivinhação ? Deixe-me apresentar, sou astrólogo estagiário. Se você não se importa, deixe-me ajudá-lo a interpretá-lo.",
  [809242973999104] = "<P_Heart> (Parece que essas garotas estão fazendo astrologia adivinhação .) </>",
  [809242973998848] = "<P_Heart> (Resmungando) </> Hmm... O horóscopo de Ellie parece cair em...",
  [809242973998592] = "Não me empurre! Estou olhando para a constelação a que Ellie pertence, se você me sacudir mais, não vou conseguir ver com clareza!",
  [809242973998336] = "Vamos, conte-nos rapidamente. Devo aceitar esse convite de viagem? Ellie deveria dizer sim para aquele cavalheiro?",
  [809242973998080] = "Oh, Debbie, não fique apenas olhando para as estrelas, conte-nos o que você vê!",
  [809242973997824] = "Wuwu, a Deusa realmente ouviu minha oração! Gentil Sr./Sra. {{|}}, que pessoas boas fiquem sob a proteção da Deusa por toda a vida!",
  [809242973997568] = "Que se dane o amanhã, vamos terminar esse drink, um brinde à vida!",
  [809242973997312] = "Heh, pessoas como nós, quem sabe onde iremos parar amanhã... mas obrigado mesmo assim.",
  [809242973997056] = "Haha, você é tão bom nisso, você é uma pessoa talentosa! É uma pena que todo o meu dinheiro esteja nesta bebida, desculpe, amigo.",
  [809242973996800] = "(Diante do destino, todos são impotentes. Mas quero trazer-lhes um sorriso, mesmo que apenas por um momento...)",
  [809242973996544] = "......Eu quero viver, quero viver continuamente, mas temos uma saída? Enquanto estivermos vivos, devemos viver assim?",
  [809242973996288] = "Mas, respirando todos os dias o pó de carvão da fábrica, talvez eu morra primeiro numa cama de hospital, em vez de num balde de ferro, quem sabe!",
  [809242973996032] = "Maldito dono da fábrica! Para economizar dinheiro, você nem instalou grades de proteção, quase me fazendo cair no ferro derretido fervente! Ainda bem que você me puxou de volta!",
  [809242973995776] = "Wuwu, Deusa, se ao menos houvesse uma maneira de distrair os convidados...",
  [809242973995520] = "Minha loja acabou de abrir, se não deixo uma boa impressão nos clientes, como posso administrar esta loja...",
  [809242973995264] = "O que fazer, o que fazer... As mesas da loja ainda estão sendo limpas, mas os clientes que aguardam estão ficando impacientes...",
  [809242973994752] = "Você deve ser o salvador enviado por Gehrman! Esse garoto chora como uma comporta, até o Gehrman não trabalha mais!",
  [809242973994496] = "<P_Heart> (As crianças adoram assistir palhaços fazendo malabarismos... Vamos tentar agir como palhaços.) </>",
  [809242973994240] = "......Por que está chorando ainda mais? Não disseram que Gehrman poderia parar o choro de uma criança? Suspiro, não sou bom em persuadir crianças......",
  [809242973993984] = "Pare de chorar! Se você chorar de novo, compro uma passagem para o mar e mando você para Gehrman Sparrow!",
  [809242973993728] = "Cale a boca, não se atreva a falar assim da minha mãe!",
  [809242973993472] = "Lembro que sua mãe tem problemas de visão, ela sempre pensa que tio Riley é duas pessoas.",
  [809242973993216] = "Não poderia ser a Estrela Azul, minha mãe apontou especificamente para mim com o dedo!",
  [809242973992960] = "Hmph, eu não me importo com o que o tio Riley disse, minha mãe me disse que essa é a Estrela Marrom, ela sempre conversa com pessoas importantes.",
  [809242973992704] = "<P_Heart> (Eles estão falando daqueles acima daquelas três estrelas no leste, certo...) </>",
  [809242973992448] = "É claro que posso dizer se o tio Riley está bêbado ou não, assim como posso dizer se é a Estrela Azul ou a Estrela Marrom! Essa é a Estrela Azul, eu garanto!",
  [809242973992192] = "Errado! Essa é a Estrela Marrom, a que está ao lado é a Estrela Azul. Aposto que tio Riley bebeu muito vinho Ronchi quando falou com você.",
  [809242973991936] = "Veja, acima das três estrelas mais brilhantes do leste, está a Estrela Azul. Tio Riley me contou.",
  [809242973991680] = "Se você ainda tem tempo para estudar aquela maldita nuvem, então arraste nossos marinheiros de volta do bar!",
  [809242973991424] = "Realmente? Mas acho que não julguei mal, olhe aquela nuvem...",
  [809242973991168] = "Ei, você está aqui! Vá dizer ao Capton que precisamos esperar até depois da tempestade para partir!",
  [809242973990912] = "<P_Heart> (Suspiro) </> Bem, bem, agora tenho que gastar dinheiro para comprar lonas de chuva.",
  [809242973990656] = "Ah, como eu disse! Meu capitão, parece que primeiro temos que preparar guarda-chuvas para o navio.",
  [809242973990400] = "Desculpe, Sr./Sra. {{|}}. Preciso terminar os preparativos para navegar o mais rápido possível, você pode encontrar meu Renny...",
  [809242973990144] = "<P_Heart> (Se eu pudesse dominar as técnicas de adivinhação , seria capaz de prever o clima futuro...) </>",
  [809242973989888] = "Você sabe do que estou falando, Sr./Sra. {{|}}. Use seus instrumentos meteorológicos ou algo assim, avise nosso Capitão que não devemos partir hoje!",
  [809242973989632] = "Olha esse tempo, parece um dia ensolarado? Capton ainda está lá verificando se a carga está no navio. Aposto que estaremos todos no fundo do mar duas horas depois de zarparmos.",
  [809242973989376] = "Irei primeiro ao Castelo Lamud para pacificar Gina, depois pedirei dinheiro emprestado a ela para ver Lily. Ela sempre atendeu todos os meus pedidos.",
  [809242973989120] = "Mas entendo o que você quer dizer, se ir em um deles não vai dar um bom resultado, então vou nos dois!",
  [809242973988864] = "Não! Se eu deixar Lily, vou perder meu amor para a vida toda... Se Gina me deixar, vou enlouquecer, não posso desistir de nenhum deles.",
  [809242973988608] = "Os resultados de você ir ao Golden Autumn Lake ou ao Lamud Castle não são bons no meu adivinhação. Deve-se ser devotado em amor; é melhor para você e para as duas jovens.",
  [809242973988352] = "<P_Heart> (É melhor aconselhá-lo.) </>",
  [809242973988096] = "Obrigado pela sua revelação! Gina, estou saindo para te encontrar agora, o canto tranquilo do castelo é feito para compartilharmos nossos corações!",
  [809242973987840] = "O Castelo Lamud é uma boa escolha.",
  [809242973987584] = "<P_Heart> (Deixe-o aprender uma lição e parar de ser mulherengo.) </>",
  [809242973987328] = "Você é realmente incrível! Eu senti a pequena Lily me chamando em meu coração... Vou procurá-la imediatamente!",
  [809242973987072] = "Golden Autumn Lake pode ser mais adequado para você.",
  [809242973986816] = "<P_Heart> (O risco no Golden Autumn Lake parece menor.) </>",
  [809242973986560] = "Grande Vidente, posso perguntar para onde devo ir?",
  [809242973986304] = "Ok, eu entendo.",
  [809242973986048] = "Por favor, me dê uma revelação! Para qual lugar devo comprar uma passagem do Trem a Vapor?",
  [809242973985792] = "Grande Vidente, <P_Yellow> Golden Autumn Lake </> e <P_Yellow> Lamud Castle </> ambos têm pessoas esperando por mim, mas meu dinheiro só me permite ir a um lugar para cumprir meu compromisso.",
  [809242973985536] = "Isso é ótimo!",
  [809242973985280] = "Sim, adivinhei de antemão que alguém aqui precisava de ajuda.",
  [809242973985024] = "Você é... não, você é um Vidente?",
  [809242973984768] = "Senhor, que tipo de revelação você precisa?",
  [809242973984512] = "Mas enquanto eu conseguir encher a barriga das crianças e fazê-las sorrir, estou disposto a ser o palhaço mais ridículo para sempre.",
  [809242973984256] = "Eu sei, sou ridículo. O público ri de mim como se estivesse rindo de um cachorro estúpido perseguindo o próprio rabo.",
  [809242973984000] = "Obrigado, obrigado... As crianças terão pão para comer hoje...",
  [809242973983744] = "<P_Heart> (Talvez eu possa atuar como palhaço e ganhar algumas dicas para ele...) </>",
  [809242973983488] = "Suspiro, parece que as crianças vão passar fome de novo...",
  [809242973983232] = "Ei, ei! Haha! Não, não vá embora, a melhor parte ainda está por vir!",
  [809242973982976] = "Esse é o pior palhaço que já vi... Aposto que ele não vai ganhar um centavo hoje.",
  [809242973982464] = "Devo dizer que estou começando a ansiar por essa história.",
  [809242973982208] = "Gehrman Sparrow foi identificado como o assassino e, para provar sua inocência, ele precisa encontrar o verdadeiro assassino...",
  [809242973981952] = "Mas os dias pacíficos não durariam para sempre. Um dia, seu professor universitário morreu misteriosamente na biblioteca.",
  [809242973981696] = "No caminho da busca pelo conhecimento, ele conhecerá professores gentis, colegas fofos e quem sabe até iniciar um romance doce e doloroso.",
  [809242973981440] = "Sim, desta vez Gehrman largou a pistola e a violência e veio para a universidade querendo se formar.",
  [809242973981184] = "O grande aventureiro famoso nos Cinco Mares e... uma universidade?",
  [809242973980928] = "Por exemplo, uma escola, por exemplo, as coisas mais preciosas para o ser humano – conhecimento e sabedoria.",
  [809242973980672] = "Todo mundo está cansado das histórias de aventura de Gehrman Sparrow; ele precisa de algum contraste, alguns... novos elementos.",
  [809242973979648] = "Talvez, mas no final, o senhor se tornará subordinado de Gehrman, assim como \"Blazing\" Danitz.",
  [809242973979392] = "E então? Gehrman travou um duelo espetacular com o Senhor da Morte?",
  [809242973979136] = "Um esqueleto gigante pairava sobre a cidade, drenando a força vital de todos; a carne cresceu sobre os ossos e os mortos rastejaram para fora de suas sepulturas.",
  [809242973978880] = "Gehrman, que chegou por acaso, percebeu as anomalias do festival e quis impedir esse horrível sacrifício.",
  [809242973978624] = "Mas o povo não sabia que seu amado senhor era na verdade uma entidade aterrorizante que retornou do reino dos mortos, e todos eles foram sacrifícios para este festival.",
  [809242973978368] = "Nesta cidade antiga, as pessoas realizarão um animado festival para celebrar o grande governo do senhor.",
  [809242973977344] = "Não tenha medo, é só uma história... não é?",
  [809242973977088] = "Estou ficando arrepiado...",
  [809242973976832] = "A cidade real estava escondida e selada sob o lago de nenúfares, junto com aquela garota do sonho dele...",
  [809242973976576] = "Ela disse a ele que a cidade, embora parecesse comum, na verdade não existia no mundo real. Era apenas um fantasma, um sonho.",
  [809242973976320] = "Na primeira noite, uma bela senhora apareceu no sonho de Gehrman, implorando-lhe que salvasse a cidade.",
  [809242973976064] = "Ele não veio destruir esta tranquilidade; afinal, o protagonista de uma história geralmente não é um vilão, hmm... mas posso tentar isso na próxima história.",
  [809242973975808] = "Na pacífica cidade de Nenúfares, as pessoas viviam vidas felizes até a chegada do grande aventureiro Gehrman Sparrow.",
  [809242973975552] = "Tão rápido, que história é essa?",
  [809242973975040] = "{{PlayerName}}, obrigado pela sua sugestão. O prazo está salvo, desde que eu acrescente mais alguns detalhes...",
  [809242973974784] = "É o amigo fofo dele, aquele esquilo dourado. No final, Gehrman precisa fazer uma escolha difícil entre o amigo e a riqueza.",
  [809242973974528] = "Mas uma caça ao tesouro não pode ser tão simples. Para obter essa riqueza, Gehrman também precisa de uma chave para abrir o tesouro.",
  [809242973974272] = "Uma árvore dourada gigante!",
  [809242973974016] = "O verdadeiro tesouro, uma árvore gigante feita de ouro.",
  [809242973973760] = "Um pequeno esquilo de pêlo dourado tornou-se seu companheiro e juntos derrotaram ladrões e inúmeros monstros, finalmente encontrando...",
  [809242973973504] = "Um dia, Gehrman Sparrow obteve um mapa do tesouro, e o grande aventureiro seguiu a trilha até o Lago Golden Autumn.",
  [809242973973248] = "Tão rápido, que tipo de história é essa?",
  [809242973972992] = "Já pensei em como escrever a próxima história.",
  [809242973972736] = "Oh, desculpe, estou um pouco animado agora. Você precisa que eu mande você de volta para o Evil Dragon Bar? É bem longe daqui.",
  [809242973972480] = "Quando chegar a hora, deixe Gehrman entrar por ali, e então diretamente...",
  [809242973972224] = "Huh? Você me seguiu até aqui também? Devo dizer que esta sugestão é muito boa.",
  [809242973971968] = "Então fique à vontade, preciso debater aqui um pouco.",
  [809242973971712] = "<P_Heart> (Parece que a Srta. Maga já está imersa em sua criação, é melhor não perturbá-la por enquanto.) </>",
  [809242973971456] = "Hmm... Gehrman deveria aparecer daqui, mas... <P_Heart> (sussurrando baixinho) </>",
  [809242973971200] = "Então, antes de mais nada, fique parado: se você cair na chaminé de alguém novamente, lembre-se de manter isso em segredo para mim!",
  [809242973970944] = "Isso é ótimo! Eu sabia! Obter a aprovação deles me deixa mais feliz do que vencer qualquer competição de culinária. Esta é a verdadeira “Certificação Medalha de Ouro”!",
  [809242973970688] = "Muito sucesso. Tenho um rabinho comprido me seguindo, é tão maravilhoso!",
  [809242973970432] = "Como é, como é? Qual é a resposta à minha nova receita?",
  [809242973970176] = "Pronto, são aqueles gatinhos! Quem sabe mais sobre peixes do que esses pequeninos? Se até eles puderem ser atraídos, significa que minha receita é realmente um sucesso!",
  [809242973969920] = "Faça-me um favor, dê um passeio pela rua e me ajude a ver como todo mundo – especialmente os gourmets mais exigentes – reage a isso?",
  [809242973969664] = "Recentemente, criei uma nova receita de peixe seco, usando algumas ervas especiais e uma técnica de defumação. Estou extremamente satisfeito com ele, mas não basta apenas eu dizer que é bom.",
  [809242973969408] = "<P_Heart> (Parece que não preciso me preocupar muito com ele.) </>",
  [809242973969152] = "Não, não posso simplesmente afundar assim... Preciso de alguém que possa me entender. Sim, eu deveria procurar Margaret; ela é sempre tão gentil e atenciosa. Talvez... talvez ela seja a única que o destino arranjou para mim.",
  [809242973968896] = "Por que... por que minha sinceridade não pode ser respondida? Talvez Lena nunca tenha me entendido de verdade.",
  [809242973968640] = "Oh, simplesmente não há como ajudá-lo!",
  [809242973968384] = "Meu cérebro e meu coração, todos os órgãos do meu corpo! Todos estão dizendo: eu te amo!",
  [809242973968128] = "Este é o 1001º dia que venho ver você, quero te contar, Lena! Eu te amo!",
  [809242973967872] = "Huh? Você quer trabalhar aqui também? Sem chance.",
  [809242973967616] = "Resultado? Talvez haja um resultado se você orar aos deuses. Tudo o que sei é que se você não se perder, o resultado será um soco a mais no seu rosto!",
  [809242973967360] = "Qual será o resultado final para os problemas que esses trabalhadores enfrentam?",
  [809242973967104] = "Droga, por que eu acreditei em você? Acabou, acabou tudo! Minhas lindas Soles!",
  [809242973966848] = "Hmph, talvez quando algum vereador precisar de votos ele pense em um jeito. Mas por enquanto o resultado é que consegui 30 Soles!",
  [809242973966592] = "Qual será o resultado final para os problemas que os trabalhadores enfrentam?",
  [809242973966336] = "Você é tão eloqüente! Eu não poderia ter dito melhor! Olhe para aqueles trabalhadores, eles parecem ter realmente entendido alguma coisa!",
  [809242973966080] = "Bem, talvez eu pudesse; Afinal, sou um leitor fiel do Tingen Daily.",
  [809242973965824] = "Siga esses temas e diga algumas bobagens como os políticos nos jornais, e tudo ficará bem. Lembre-se, você deve <P_Yellow> escolher o tema certo </> !",
  [809242973965568] = "Por fim, fale sobre os <P_Yellow> trabalhadores que precisam protestar através de greves </> .",
  [809242973965312] = "Então, vamos falar sobre o <P_Yellow> dono da fábrica retendo os salários dos trabalhadores </> .",
  [809242973965056] = "Ouça, primeiro vamos falar sobre as <P_Yellow> duras condições de trabalho na fábrica </> .",
  [809242973964800] = "Você parece bastante capaz... Não importa, contanto que você possa dizer algumas palavras de acordo com o tema, 30 Soles serão seus. Ninguém se importará com esse maldito movimento de protesto.",
  [809242973964544] = "Este bairro está cheio de bêbados cujas línguas foram arruinadas pelo álcool; eles não conseguem nem terminar uma única frase corretamente.",
  [809242973964032] = "Estou prestes a fazer um discurso, o que devo fazer... Você! Sim, você! Venha e me faça um favor!",
}
